import { chromium, expect } from '../../../../apps/node_modules/@playwright/test/index.mjs';
import { readFileSync, lstatSync, writeFileSync } from 'node:fs';

const file = process.env.HC_GATEWAY_BROWSER_FIXTURE_FILE;
if (!file || !lstatSync(file).isFile() || (lstatSync(file).mode & 0o077) !== 0) throw new Error('Private browser fixture required');
const fixture = JSON.parse(readFileSync(file, 'utf8'));
const portal = new URL(fixture.portal_url);
if (portal.protocol !== 'https:' || portal.hostname !== 'portal.harness.localhost' || !/^[A-Za-z0-9_-]{43}$/.test(fixture.portal_cookie)) throw new Error('Invalid controlled browser fixture');
const native = new URL(`https://i-${fixture.instance_id.replaceAll('-', '')}.harness.localhost:${portal.port}`);
let stage = 'launch';
let browser;
const diagnostics={opened:0,closed:0,errors:0,active:0,logout_status:0,me_after_logout:0};
try {
 browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH, args: ['--no-proxy-server'] });
 const context = await browser.newContext({ ignoreHTTPSErrors: true });
 await context.addCookies([{ name: '__Host-hc_session', value: fixture.portal_cookie, url: portal.origin + '/', secure: true, httpOnly: true, sameSite: 'Lax' }]);
 const page = await context.newPage();
 stage = 'portal-details';
 await page.goto(`${portal.origin}/app/instances/${fixture.instance_id}`);
 await expect(page.getByRole('button', { name: '进入工作空间', exact: true })).toBeEnabled();
 stage = 'copied-ticket';
 const copied = await page.evaluate(async instance => {
  const user = await (await fetch('/v1/me')).json();
  const details = await (await fetch(`/v1/instances/${instance}`)).json();
  const origin = `https://${details.access_host}${location.port ? ':' + location.port : ''}`;
  const challenge = await (await fetch(origin + '/__dsh/challenge', { credentials: 'include', redirect: 'error', cache: 'no-store' })).json();
  const response = await fetch(`/v1/instances/${instance}:access`, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': user.csrf_token }, body: JSON.stringify({ challenge_id: challenge.challenge_id }) });
  if (!response.ok) throw new Error('Controlled test handoff rejected');
  return response.json();
 }, fixture.instance_id);
 const attacker = await browser.newContext({ ignoreHTTPSErrors: true });
 const copiedResult = await attacker.request.post(copied.handoff_url, { headers: { Origin: portal.origin }, form: { ticket: copied.ticket, challenge_id: copied.challenge_id }, maxRedirects: 0 });
 expect(copiedResult.status()).toBe(403); await attacker.close();
 stage = 'real-handoff';
 const popupEvent = page.waitForEvent('popup');
 await page.getByRole('button', { name: '进入工作空间', exact: true }).click();
 const popup = await popupEvent;
 let frames = 0, rootStatus = 0;
 const active = new Set();
 popup.on('response', response => { if (response.url() === native.origin + '/') rootStatus = response.status(); });
 popup.on('websocket', socket => { if (new URL(socket.url()).pathname !== '/api/remote.mux') return; diagnostics.opened++;active.add(socket); socket.on('framereceived', () => frames++); socket.on('socketerror',()=>{diagnostics.errors++});socket.on('close', () => {diagnostics.closed++;active.delete(socket)}); });
 await popup.waitForURL(url => url.origin === native.origin && url.pathname === '/', { timeout: 20_000 });
 await popup.waitForLoadState('domcontentloaded');
 await expect.poll(() => rootStatus, { timeout: 5000 }).toBe(200);
 stage = 'native-websocket';
 await expect.poll(() => frames, { timeout: 15_000 }).toBeGreaterThan(0);
 expect(active.size).toBeGreaterThan(0);
 expect(await popup.evaluate(() => window.opener === null)).toBe(true);
 expect(popup.url()).not.toContain('token');
 stage = 'cookie-boundary';
 const cookies = await context.cookies(native.origin);
 expect(cookies.some(cookie => cookie.name === '__Host-hc_access' && cookie.httpOnly && cookie.secure && cookie.sameSite === 'Strict' && cookie.domain === native.hostname)).toBe(true);
 expect(cookies.some(cookie => cookie.name === '__Host-hc_session' || cookie.name === '__Host-hc_challenge' || cookie.name.startsWith('dsh-auth-'))).toBe(false);
 expect(await popup.evaluate(() => Object.values(localStorage).some(value => /__Host-hc|v1\.synthetic/.test(value)))).toBe(false);
 expect((await context.request.post(native.origin + '/api/action', { headers: { Origin: portal.origin }, data: 'forbidden' })).status()).toBe(403);
 expect((await context.request.get(native.origin + '/?token=forbidden')).status()).toBe(403);
 stage = 'logout-request';
 await page.goto(portal.origin + '/login');
 await expect(page.getByRole('button', { name: '退出登录', exact: true })).toBeVisible();
 const started = Date.now();
 const logoutResponse=page.waitForResponse(response=>new URL(response.url()).pathname==='/auth/logout' && response.request().method()==='POST');
 await page.getByRole('button', { name: '退出登录', exact: true }).click();
 diagnostics.logout_status=(await logoutResponse).status();
 expect(diagnostics.logout_status).toBe(204);
 diagnostics.me_after_logout=(await context.request.get(portal.origin+'/v1/me')).status();
 expect(diagnostics.me_after_logout).toBe(401);
 stage = 'logout-login-page';
 await expect(page).toHaveURL(/\/login$/);
 stage = 'logout-socket-close';
 await expect.poll(() => {diagnostics.active=active.size;return active.size}, { timeout: 25_000 }).toBe(0);
 expect(Date.now() - started).toBeLessThan(30_000);
 stage = 'logout-http-denial';
 expect((await context.request.get(native.origin + '/')).status()).toBe(401);
 writeFileSync(file + '.status.json', JSON.stringify({ passed: true, stage: 'complete', paid_requests: 0, logout_closed_within_30s: true, native_frames_observed: frames > 0 }), { mode: 0o600 });
} catch {
 writeFileSync(file + '.status.json', JSON.stringify({ passed: false, stage,diagnostics }), { mode: 0o600 });
 process.exitCode = 1;
} finally { await browser?.close(); }
